-- ============================================================
-- ЕРН — общий датасет (лица без деления на физических и должностных)
-- Источник: ern_full.sql, выгрузка от 12.11.2026, 16:50:09
-- Собрано: 19.11.2026
-- Дисклеймер: данные синтетические, артефакты допустимы
--
-- 230 лиц; признак должностного лица здесь не хранится.
-- Реестр должностных лиц — отдельный файл dltos.sql, связь по person_id.
--
-- Связи приведены к одной записи на пару: 74 -> 37 (зеркальные копии
-- «Брат»/«Сестра»/«Супруг(а)» свёрнуты, у родительских пар направление
-- person_id_1 — родитель, person_id_2 — ребёнок).
-- Записи ЗАГС: 36 -> 18 (обратные копии «-R» отброшены).
-- Подтверждение родства записью акта — колонка kinship.civil_id.
-- ============================================================

PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

DROP TABLE IF EXISTS kinship;
DROP TABLE IF EXISTS civil_registry;
DROP TABLE IF EXISTS divorce;
DROP TABLE IF EXISTS emancipation;
DROP TABLE IF EXISTS legal_capacity;
DROP TABLE IF EXISTS employment_service;
DROP TABLE IF EXISTS tax_registration;
DROP TABLE IF EXISTS driver_license;
DROP TABLE IF EXISTS education;
DROP TABLE IF EXISTS military_registration;
DROP TABLE IF EXISTS fingerprint_registration;
DROP TABLE IF EXISTS social_insurance;
DROP TABLE IF EXISTS parental_rights;
DROP TABLE IF EXISTS guardianship;
DROP TABLE IF EXISTS passport_rf;
DROP TABLE IF EXISTS person;

-- Лица. Признака «физическое/должностное лицо» нет: принадлежность
-- к должностным лицам задаётся файлом dltos.sql.
CREATE TABLE person (
    person_id         TEXT PRIMARY KEY,
    last_name         TEXT NOT NULL,
    first_name        TEXT NOT NULL,
    middle_name       TEXT NOT NULL,
    gender            TEXT,
    birth_date        TEXT,
    birth_place       TEXT,
    citizenship       TEXT,          -- как в выгрузке: «РФ, Таджикистан»
    citizenship_codes TEXT,          -- нормализовано: «RF,TJ»
    snils             TEXT,
    inn               TEXT,
    marital_status    TEXT,
    address           TEXT
);

CREATE TABLE passport_rf (
    passport_id INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    series      TEXT NOT NULL,
    number      TEXT NOT NULL,
    issue_date  TEXT,
    dept_code   TEXT,
    issued_by   TEXT,
    is_valid    INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX idx_passport_person ON passport_rf(person_id);

CREATE TABLE civil_registry (
    zags_id     TEXT PRIMARY KEY,
    person_id_1 TEXT NOT NULL REFERENCES person(person_id),
    person_id_2 TEXT NOT NULL REFERENCES person(person_id),
    relation    TEXT NOT NULL,       -- sibling | spouse | parent
    act_number  TEXT,
    act_date    TEXT,
    zags_name   TEXT
);

CREATE TABLE kinship (
    kinship_id  INTEGER PRIMARY KEY,
    person_id_1 TEXT NOT NULL REFERENCES person(person_id),  -- родитель
    person_id_2 TEXT NOT NULL REFERENCES person(person_id),  -- ребёнок
    relation    TEXT NOT NULL,       -- sibling | spouse | parent
    act_number  TEXT,
    act_date    TEXT,
    zags_name   TEXT,
    civil_id    TEXT REFERENCES civil_registry(zags_id)  -- NULL: акт не найден
);
CREATE UNIQUE INDEX idx_kinship_edge ON kinship(person_id_1, person_id_2, relation);

CREATE TABLE divorce (
    divorce_id  INTEGER PRIMARY KEY,
    person_id_1 TEXT NOT NULL REFERENCES person(person_id),
    person_id_2 TEXT NOT NULL REFERENCES person(person_id),
    act_number  TEXT,
    act_date    TEXT,
    zags_name   TEXT
);

CREATE TABLE emancipation (
    emancipation_id INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    act_date    TEXT,
    act_number  TEXT,
    authority   TEXT
);

CREATE TABLE legal_capacity (
    capacity_id INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    status      TEXT NOT NULL,       -- дееспособен | ограничен | недееспособен
    act_date    TEXT,
    act_number  TEXT,
    authority   TEXT
);

CREATE TABLE employment_service (
    employment_id INTEGER PRIMARY KEY,
    person_id     TEXT NOT NULL REFERENCES person(person_id),
    status        TEXT,
    registration_date TEXT,
    center_name   TEXT
);

CREATE TABLE tax_registration (
    tax_id      INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    status      TEXT,                -- нет | ИП | НПД
    registration_date TEXT,
    ogrnip      TEXT
);
CREATE INDEX idx_tax_ogrnip ON tax_registration(ogrnip);

CREATE TABLE driver_license (
    license_id  INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    number      TEXT,
    issue_date  TEXT,
    expiry_date TEXT,
    categories  TEXT,
    issued_by   TEXT
);

CREATE TABLE education (
    education_id INTEGER PRIMARY KEY,
    person_id    TEXT NOT NULL REFERENCES person(person_id),
    institution  TEXT,
    level        TEXT,
    specialty    TEXT,
    graduation_year INTEGER,
    qualification TEXT
);

CREATE TABLE military_registration (
    mil_id      INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    status      TEXT,
    category    TEXT,
    registration_date TEXT,
    commissariat TEXT
);

CREATE TABLE fingerprint_registration (
    fp_id       INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    registration_date TEXT,
    authority   TEXT,
    photo_date  TEXT
);

CREATE TABLE social_insurance (
    insurance_id INTEGER PRIMARY KEY,
    person_id    TEXT NOT NULL REFERENCES person(person_id),
    oms_number   TEXT,
    pension_number TEXT,
    social_number TEXT,
    registration_date TEXT
);

CREATE TABLE parental_rights (
    parental_id INTEGER PRIMARY KEY,
    person_id   TEXT NOT NULL REFERENCES person(person_id),
    action_type TEXT,                -- лишение
    act_number  TEXT,
    act_date    TEXT,
    authority   TEXT
);
-- ВНИМАНИЕ: в выгрузке нет child_id, поэтому ребёнок здесь не указан.

CREATE TABLE guardianship (
    guardianship_id INTEGER PRIMARY KEY,
    ward_id     TEXT NOT NULL REFERENCES person(person_id),
    guardian_id TEXT NOT NULL REFERENCES person(person_id),
    form        TEXT,
    start_date  TEXT,
    act_number  TEXT
);

-- ------------------------------ данные ------------------------------

-- person: 230

-- passport_rf: 230

-- civil_registry: 18

-- kinship: 37, из них подтверждено ЗАГС: 18

-- divorce: 7

-- emancipation: 5

-- legal_capacity: 13

-- employment_service: 38

-- tax_registration: 230

-- driver_license: 230

-- education: 219

-- military_registration: 111

-- fingerprint_registration: 230

-- social_insurance: 230

-- parental_rights: 13

-- guardianship: 0

COMMIT;

